node -v && cat > /tmp/sms-selfcheck.mjs <<'EOF'
import { checkSms } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/ours-g1-2/bot.mjs';
const to = (o = {}) => ({ phone: '+13125550142', timeZone: 'America/Chicago', marketingConsent: true, optedOutAt: null, ...o });
const mk = (kind, body, toO) => ({ kind, body, to: to(toO) });
const MKT = 'Sale today! Reply STOP to opt out.';
const T = 'Your login code is 123456.';
const at = (iso) => new Date(iso);
const cases = [
  ['mkt 08:00 CDT allowed (inclusive start)', mk('marketing', MKT), at('2026-10-22T13:00:00Z'), true, null],
  ['mkt 07:59 CDT blocked', mk('marketing', MKT), at('2026-10-22T12:59:00Z'), false, 'quiet_hours'],
  ['mkt 20:59 CDT allowed', mk('marketing', MKT), at('2026-10-23T01:59:00Z'), true, null],
  ['mkt 21:00 CDT blocked (end exclusive)', mk('marketing', MKT), at('2026-10-23T02:00:00Z'), false, 'quiet_hours'],
  ['mkt no consent', mk('marketing', MKT, { marketingConsent: false }), at('2026-10-22T18:00:00Z'), false, 'no_marketing_consent'],
  ['mkt consent absent', mk('marketing', MKT, { marketingConsent: undefined }), at('2026-10-22T18:00:00Z'), false, 'no_marketing_consent'],
  ['mkt opted out', mk('marketing', MKT, { optedOutAt: '2026-10-01T10:00:00Z' }), at('2026-10-22T18:00:00Z'), false, 'opted_out'],
  ['mkt no STOP instruction', mk('marketing', 'Sale today!'), at('2026-10-22T18:00:00Z'), false, 'missing_opt_out_instructions'],
  ['mkt bad zone', mk('marketing', MKT, { timeZone: 'Mars/Olympus' }), at('2026-10-22T18:00:00Z'), false, 'invalid_time_zone'],
  ['txn 03:00 local allowed (no hour rule)', mk('transactional', T), at('2026-10-22T08:00:00Z'), true, null],
  ['txn no consent needed', mk('transactional', T, { marketingConsent: false }), at('2026-10-22T18:00:00Z'), true, null],
  ['txn opted out blocked', mk('transactional', T, { optedOutAt: '2026-10-01T10:00:00Z' }), at('2026-10-22T18:00:00Z'), false, 'opted_out'],
  ['bad opt-out record', mk('transactional', T, { optedOutAt: 'yesterday' }), at('2026-10-22T18:00:00Z'), false, 'invalid_opt_out_record'],
  ['bad kind', mk('promo', MKT), at('2026-10-22T18:00:00Z'), false, 'invalid_message_kind'],
  ['bad phone', mk('transactional', T, { phone: '3125550142' }), at('2026-10-22T18:00:00Z'), false, 'invalid_phone'],
  ['empty body', mk('transactional', '  '), at('2026-10-22T18:00:00Z'), false, 'invalid_body'],
  ['bad now', mk('transactional', T), new Date('nope'), false, 'invalid_now'],
];
let fail = 0;
for (const [name, m, now, ok, reason] of cases) {
  const r = checkSms(m, now);
  const pass = r.allowed === ok && r.reason === reason;
  if (!pass) fail++;
  console.log(pass ? 'PASS' : 'FAIL', name, JSON.stringify(r));
}
console.log(fail ? `${fail} FAILED` : 'all passed');
process.exitCode = fail ? 1 : 0;
EOF
for tz in UTC Asia/Tokyo America/Los_Angeles; do echo "--- server TZ=$tz"; TZ=$tz node /tmp/sms-selfcheck.mjs; done; rm -f /tmp/sms-selfcheck.mjs

